import{_ as i,C as a,o as l,c as h,j as d,a as e,E as o,a5 as n}from"./chunks/framework.BYIUCCsM.js";const q=JSON.parse('{"title":"提及","description":"","frontmatter":{},"headers":[],"relativePath":"components/mention.md","filePath":"components/mention.md","lastUpdated":1787714572000}'),s={name:"components/mention.md"},p={id:"提及",tabindex:"-1"};function u(m,t,b,x,g,f){const r=a("Badge"),c=a("XhDemo");return l(),h("div",null,[d("h1",p,[t[0]||(t[0]=e("提及 ",-1)),o(r,{type:"info",text:"mention"}),t[1]||(t[1]=e()),t[2]||(t[2]=d("a",{class:"header-anchor",href:"#提及","aria-label":'Permalink to "提及 <Badge type="info" text="mention" />"'},"​",-1))]),t[3]||(t[3]=n('<p>在正文里打一个前缀字符就弹出候选，选中后把引用插进文本。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>评论、聊天、任务描述里 @ 某个人或 # 某个条目。</li><li>需要多种前缀各带一份候选。</li></ul><h2 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h2><ul><li>整个输入框的值就是选中项：用<a href="./combobox">组合框</a>。</li><li>只是补全普通词汇：用<a href="./combobox">组合框</a>或原生自动补全。</li></ul><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li>多种前缀各自映射一份候选。</li><li><code>onQueryChange</code> 给出当前查询串，异步候选据此拉取。</li><li>正文可受控，选中时另有回调。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="基础用法" tabindex="-1">基础用法 <a class="header-anchor" href="#基础用法" aria-label="Permalink to &quot;基础用法&quot;">​</a></h3><p>在正文里敲 @ 才开候选，选中的那条被插到光标处，前后文一字不动</p>',10)),o(c,{src:"mention/01-basic"}),t[4]||(t[4]=d("h3",{id:"多种前缀",tabindex:"-1"},[e("多种前缀 "),d("a",{class:"header-anchor",href:"#多种前缀","aria-label":'Permalink to "多种前缀"'},"​")],-1)),t[5]||(t[5]=d("p",null,"@ 提人、# 打标签共用一个输入框，query-change 会报回是哪个前缀触发的",-1)),o(c,{src:"mention/02-multi-prefix"}),t[6]||(t[6]=d("h3",{id:"候选里的自定义内容",tabindex:"-1"},[e("候选里的自定义内容 "),d("a",{class:"header-anchor",href:"#候选里的自定义内容","aria-label":'Permalink to "候选里的自定义内容"'},"​")],-1)),t[7]||(t[7]=d("p",null,"手写各部件即可在候选行里放头像与职位；插回正文的那段字取自 item-text",-1)),o(c,{src:"mention/03-custom-item"}),t[8]||(t[8]=d("h3",{id:"受控正文与选中回调",tabindex:"-1"},[e("受控正文与选中回调 "),d("a",{class:"header-anchor",href:"#受控正文与选中回调","aria-label":'Permalink to "受控正文与选中回调"'},"​")],-1)),t[9]||(t[9]=d("p",null,"正文由宿主持有，select 事件报回插进去的是哪一条，用来攒收件人名单",-1)),o(c,{src:"mention/04-controlled"}),t[10]||(t[10]=d("h3",{id:"异步候选",tabindex:"-1"},[e("异步候选 "),d("a",{class:"header-anchor",href:"#异步候选","aria-label":'Permalink to "异步候选"'},"​")],-1)),t[11]||(t[11]=d("p",null,"查询串每变一次就重新去远端查一遍，等结果的这段时间浮层里空着",-1)),o(c,{src:"mention/05-async"}),t[12]||(t[12]=n('<h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-mention&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhMentionContent</code> <code>XhMentionInput</code> <code>XhMentionItem</code> <code>XhMentionItemText</code> <code>XhMentionPositioner</code> <code>XhMentionRoot</code></td></tr><tr><td>组合式函数</td><td><code>useMention</code></td></tr><tr><td>状态机</td><td><code>mentionMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/mention.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;mention&quot;</code>：<strong><code>root</code></strong> · <strong><code>input</code></strong> · <code>positioner</code> · <strong><code>content</code></strong> · <code>item</code> · <code>item-text</code></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>prefix</code></td><td><code>string | string[]</code></td><td></td><td>开候选的前缀字符，缺省 &#39;@&#39;。给数组即多种前缀并存，宿主按 onQueryChange 报回的 prefix 分流。 前缀必须紧跟在行首或空白之后，邮箱地址里的 @ 因此不会误触发。</td></tr><tr><td><code>collection</code></td><td><code>MentionNode[]</code></td><td></td><td>候选数据，显示文本与禁用的事实源。过滤仍归调用方：交进来的就是此刻该显示的那几条。 组件不管怎么筛，它只负责把查询串交出去。</td></tr><tr><td><code>value</code></td><td><code>string</code></td><td></td><td>整段正文。给定即受控：cell 直读 prop，写只发 onValueChange 不落内部值。</td></tr><tr><td><code>defaultValue</code></td><td><code>string</code></td><td></td><td></td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td><td>整个控件禁用：输入框用原生 disabled，候选一概不开。</td></tr><tr><td><code>readOnly</code></td><td><code>boolean</code></td><td></td><td>只读：正文仍可聚焦与复制，改不动，候选也不开。</td></tr><tr><td><code>invalid</code></td><td><code>boolean</code></td><td></td><td>校验失败标注：描边与聚焦环换成失败色，同时经 aria-invalid 上报。</td></tr><tr><td><code>placeholder</code></td><td><code>string</code></td><td></td><td>输入框占位文字。不给就整条不输出，作者写在 input 部件上的那份因此留得住。</td></tr><tr><td><code>loop</code></td><td><code>boolean</code></td><td></td><td>方向键走到尽头是否回绕，默认 true。</td></tr><tr><td><code>placement</code></td><td><code>Placement</code></td><td></td><td></td></tr><tr><td><code>dir</code></td><td><code>Direction</code></td><td></td><td>文字方向，缺省 ltr。只改写浮层在行内轴上 start 与 end 的落点。</td></tr><tr><td><code>offset</code></td><td><code>number</code></td><td></td><td></td></tr><tr><td><code>translations</code></td><td><code>MentionTranslations</code></td><td></td><td></td></tr><tr><td><code>variant</code></td><td><code>ControlVariant</code></td><td></td><td>形态：outline / subtle / ghost，决定输入框的描边与底色怎么用。</td></tr><tr><td><code>tone</code></td><td><code>Tone</code></td><td></td><td>语气：brand / neutral / success / warning / danger / info，决定聚焦与高亮用哪族颜色。</td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td>尺寸：sm / md / lg，决定输入框内边距与字号档位。</td></tr><tr><td><code>onValueChange</code></td><td><code>(details: MentionValueChangeDetails) =&gt; void</code></td><td></td><td>正文变化回调；受控时是唯一出口。</td></tr><tr><td><code>onQueryChange</code></td><td><code>(details: MentionQueryChangeDetails) =&gt; void</code></td><td></td><td>查询串变化回调：调用方据此重新过滤候选。收起时报 null。</td></tr><tr><td><code>onSelect</code></td><td><code>(details: MentionSelectDetails) =&gt; void</code></td><td></td><td>候选被插进正文时回调，带上是哪一条。</td></tr><tr><td><code>onOpenChange</code></td><td><code>(details: MentionOpenChangeDetails) =&gt; void</code></td><td></td><td>浮层开合回调。</td></tr></tbody></table><h2 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h2><p>自定义元素派发这些事件，Vue 组件对应同名 emit；载荷都在 <code>detail</code> 上。可双向绑定的值另有 <code>update:xxx</code>，见 Props。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>value-change</code></td><td><code>MentionValueChangeDetails</code></td><td>正文变化；detail 为 <code>{ value: string }</code></td></tr><tr><td><code>query-change</code></td><td><code>MentionQueryChangeDetails</code></td><td>查询串变化；detail 为 <code>{ query, prefix }</code>，作者据此过滤候选；收起时报 null</td></tr><tr><td><code>select</code></td><td><code>MentionSelectDetails</code></td><td>候选被插进正文；detail 为 <code>{ value, label, prefix }</code></td></tr><tr><td><code>open-change</code></td><td><code>MentionOpenChangeDetails</code></td><td>浮层开合；detail 为 <code>{ open: boolean }</code></td></tr></tbody></table><h2 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h2><p>作者能拿到载荷的插槽。只转发内容、不带载荷的默认插槽不在此列——那类直接写子节点即可。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhMentionRoot</code></td><td><code>default</code></td><td><code>MentionRootSlotProps</code></td><td></td></tr><tr><td><code>XhMentionRoot</code></td><td><code>item</code></td><td><code>MentionNodeMeta</code></td><td>铺开 collection 时每条候选的文本插槽。</td></tr></tbody></table><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><p>对外可见的状态落在 <code>data-state</code> 上，写样式与断言都读它：</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>root</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>input</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>positioner</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>content</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr></tbody></table><p>状态机内部转移，写样式与业务都用不到；要监听变化请看上面的「事件」。</p><p><strong>状态</strong>：<code>open</code> · <code>closed</code></p><p><strong>事件</strong>：<code>OPEN</code> · <code>CLOSE</code> · <code>ESCAPE</code> · <code>INPUT.CHANGE</code> · <code>CARET.SYNC</code> · <code>VALUE.SET</code> · <code>ITEM.HIGHLIGHT</code> · <code>ITEM.SELECT</code> · <code>ITEMS.SYNC</code></p><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>useMention</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>open</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>collection</code></td><td><code>readonly MentionNodeMeta[]</code></td><td>collection 推出的候选元信息，按数据顺序排列；没给 collection 即空数组。</td></tr><tr><td><code>value</code></td><td><code>string</code></td><td>整段正文。</td></tr><tr><td><code>query</code></td><td><code>string | null</code></td><td>当前查询串；没有触发时为 null。</td></tr><tr><td><code>activePrefix</code></td><td><code>string | null</code></td><td>触发本次查询的前缀；没有触发时为 null。</td></tr><tr><td><code>highlightedValue</code></td><td><code>string | null</code></td><td>高亮候选；收起时为 null。焦点不在它身上，只经 aria-activedescendant 上报。</td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>isHighlighted</code></td><td><code>(value: string) =&gt; boolean</code></td><td></td></tr><tr><td><code>setValue</code></td><td><code>(next: string) =&gt; void</code></td><td>整段改写正文，浮层随之收起。</td></tr><tr><td><code>close</code></td><td><code>() =&gt; void</code></td><td></td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getInputProps</code></td><td><code>(props?: MentionInputProps) =&gt; T[&#39;textarea&#39;]</code></td><td>不传参即多行 textarea。</td></tr><tr><td><code>getPositionerProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getContentProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getItemProps</code></td><td><code>(props: MentionItemProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getItemTextProps</code></td><td><code>(props: MentionItemProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/combobox/#keyboardinteraction" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>前缀字符</code></td><td>光标前是行首或空白</td><td>开候选浮层，并把前缀到光标之间那段作为查询串交给宿主</td></tr><tr><td><code>可打印字符</code></td><td>open</td><td>查询串跟着变长，过滤由调用方按 onQueryChange 自己做</td></tr><tr><td><code>ArrowDown</code></td><td>open</td><td>高亮移到下一个候选（禁用项跳过、尽头按 loop 回绕），焦点不动</td></tr><tr><td><code>ArrowUp</code></td><td>open</td><td>高亮移到上一个候选（禁用项跳过、尽头按 loop 回绕），焦点不动</td></tr><tr><td><code>Enter</code></td><td>open, 有高亮且未禁用</td><td>把候选文本插到光标处替换查询串，光标落到插入内容之后，浮层收起；这次回车不换行</td></tr><tr><td><code>Enter</code></td><td>open, 无可提交候选</td><td>照常换行，只把浮层收起来</td></tr><tr><td><code>Escape</code></td><td>open</td><td>收起浮层且正文不变；光标不离开这个触发点就不再自动展开</td></tr><tr><td><code>Tab</code> / <code>Shift+Tab</code></td><td>open</td><td>收起浮层且不拦按键，焦点按 Tab 序列自然离开</td></tr><tr><td><code>ArrowLeft</code> / <code>ArrowRight</code> / <code>Home</code> / <code>End</code></td><td>任意时候</td><td>一律不接管：光标照常移动，触发按新的光标位置重算，挪出查询串即收起</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>input</code></td><td><code>aria-activedescendant</code></td><td><code>item</code> 部件的 id | undefined</td></tr><tr><td><code>input</code></td><td><code>aria-autocomplete</code></td><td>&#39;list&#39;</td></tr><tr><td><code>input</code></td><td><code>aria-controls</code></td><td><code>content</code> 部件的 id</td></tr><tr><td><code>input</code></td><td><code>aria-expanded</code></td><td>undefined | &#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>input</code></td><td><code>aria-haspopup</code></td><td>&#39;listbox&#39;</td></tr><tr><td><code>input</code></td><td><code>aria-invalid</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>input</code></td><td><code>aria-label</code></td><td>props.translations.input</td></tr><tr><td><code>input</code></td><td><code>role</code></td><td>undefined | &#39;combobox&#39;</td></tr><tr><td><code>content</code></td><td><code>aria-label</code></td><td>props.translations.content</td></tr><tr><td><code>content</code></td><td><code>role</code></td><td>&#39;listbox&#39;</td></tr><tr><td><code>item</code></td><td><code>aria-disabled</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>item</code></td><td><code>aria-selected</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>item</code></td><td><code>role</code></td><td>&#39;option&#39;</td></tr></tbody></table><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/mention.css</code> 按部件选择：<code>[data-scope=&quot;mention&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 与 <code>xihan.motion</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-invalid</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-readonly</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>root</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>root</code></td><td><code>data-tone</code></td><td>props.tone</td></tr><tr><td><code>root</code></td><td><code>data-variant</code></td><td>props.variant</td></tr><tr><td><code>input</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>input</code></td><td><code>data-invalid</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>input</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>positioner</code></td><td><code>data-hidden</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>positioner</code></td><td><code>data-placement</code></td><td>定位引擎算出的实际落位</td></tr><tr><td><code>positioner</code></td><td><code>data-positioned</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>positioner</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>positioner</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>positioner</code></td><td><code>data-tone</code></td><td>props.tone</td></tr><tr><td><code>positioner</code></td><td><code>data-variant</code></td><td>props.variant</td></tr><tr><td><code>content</code></td><td><code>data-placement</code></td><td>定位引擎算出的实际落位</td></tr><tr><td><code>content</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件皮肤读的组件级令牌，写在组件自身或任意祖先上都生效。缺省值来自<a href="./../guide/theme">设计令牌</a>，不设即按缺省走。</p><p><code>--xh-mention-content-bg</code> · <code>--xh-mention-content-border</code> · <code>--xh-mention-content-fg</code> · <code>--xh-mention-content-gap</code> · <code>--xh-mention-content-max-h</code> · <code>--xh-mention-content-max-w</code> · <code>--xh-mention-content-min-w</code> · <code>--xh-mention-content-px</code> · <code>--xh-mention-content-py</code> · <code>--xh-mention-content-radius</code> · <code>--xh-mention-content-shadow</code> · <code>--xh-mention-input-bg</code> · <code>--xh-mention-input-bg-disabled</code> · <code>--xh-mention-input-bg-readonly</code> · <code>--xh-mention-input-border</code> · <code>--xh-mention-input-border-focus</code> · <code>--xh-mention-input-border-hover</code> · <code>--xh-mention-input-border-invalid</code> · <code>--xh-mention-input-fg</code> · <code>--xh-mention-input-font-size</code> · <code>--xh-mention-input-h</code> · <code>--xh-mention-input-min-w</code> · <code>--xh-mention-input-px</code> · <code>--xh-mention-input-py</code> · <code>--xh-mention-input-radius</code> · <code>--xh-mention-item-bg-hover</code> · <code>--xh-mention-item-fg</code> · <code>--xh-mention-item-font-size</code> · <code>--xh-mention-item-gap</code> · <code>--xh-mention-item-leading</code> · <code>--xh-mention-item-px</code> · <code>--xh-mention-item-py</code> · <code>--xh-mention-item-radius</code> · <code>--xh-mention-layer</code> · <code>--xh-mention-placeholder-fg</code></p><h2 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h2><p>关键帧 <code>xh-pop-in</code> · <code>xh-pop-out</code> 随皮肤自带，不引用别处文件里的名字；状态切换走 <code>transition</code>。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>输入宿主可以是<a href="./text-field">文本输入</a>的多行形态，或 AI 场景里的<a href="./composer">消息编辑器</a>。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>候选按最近使用排序：@ 的对象高度重复。</li><li>插入后的引用要能整体删除，别让用户一个字一个字退。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>候选异步且没有在途反馈：用户以为没人可 @。</li><li>前缀字符在正文里本来就常用（比如 <code>#</code> 在代码里），却不给退出方式。</li></ul>',47))])}const y=i(s,[["render",u]]);export{q as __pageData,y as default};
